11	// settleWindowOpts 控制一笔“已结算”请求备份的构造：
12	//   - approved：false 为直接受理路径，true 为超门槛经批准后预留路径；
13	//   - actualFee：结算实际费用（允许为零）；
14	//   - settledAt：备份记载的结算时刻；
15	//   - mutate：在序列化前进一步调整请求/策略/会话字段。
16	//
17	// 除结算时刻由参数指定外，其余计时与金额完全自洽，因此恢复能否成功只取决于
18	// 结算时刻是否落在有效预留期内。两路径均：费用 20、最长预留时长 2h；直接
19	// 受理于 t0，批准路径提交于 t0、于 t0+30m 批准并预留（等待 1h）。
20	type settleWindowOpts struct {
21		approved  bool
22		actualFee int64
23		settledAt time.Time
24		mutate    func(*requestBackupV1, *policyBackupV1, *sessionBackupV1)
25	}
