27	func buildSettleWindowBackup(t *testing.T, t0 time.Time, opts settleWindowOpts) []byte {
28		t.Helper()
29		const fee int64 = 20
30		r := requestBackupV1{
31			PolicyID: "p", RequestID: "late", AccountID: "u1", PayerAccountID: "payer",
32			SessionID: "s1", Operation: "charge", Payee: "shop",
33			EstimatedFee: fee,
34			ActualFee:    opts.actualFee,
35			State:        int(RequestSettled),
36			CreatedAt:    timeJSON(t0),
37			SettledAt:    timeJSON(opts.settledAt),
38		}
39		pol := policyBackupV1{
40			ID: "p", PayerAccountID: "payer", AllowedAccountIDs: []string{"u1"},
41			Operation: "charge", Payee: "shop",
42			StartsAt:           timeJSON(t0.Add(-time.Hour)),
43			EndsAt:             timeJSON(t0.Add(24 * time.Hour)),
44			MaxPerRequest:      100,
45			MaxTotal:           1000,
46			MaxReserveDuration: durationJSON(2 * time.Hour),
47			SpentTotal:         opts.actualFee,
48		}
49		sess := sessionBackupV1{
50			ID: "s1", AccountID: "u1", DeviceID: "d1",
51			ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0.Add(-2 * time.Hour)),
52		}
53		if opts.approved {
54			pol.ApprovalThreshold = 10
55			pol.ApprovalWait = durationJSON(time.Hour)
56			// 提交 t0、等待截止 t0+1h，于 t0+30m 批准并实际预留；预留自批准时刻
57			// 起算，截止 t0+2h30m（等待审批的 30m 不计入）。
58			r.WaitDeadline = timeJSON(t0.Add(time.Hour))
59			r.ReservedAt = timeJSON(t0.Add(30 * time.Minute))
60			r.ReserveDuration = durationJSON(2 * time.Hour)
61			r.ReserveDeadline = timeJSON(t0.Add(2*time.Hour + 30*time.Minute))
62			r.ApproverAccountID = "payer"
63			r.DecidedAt = timeJSON(t0.Add(30 * time.Minute))
64		} else {
65			r.ReservedAt = timeJSON(t0)
66			r.ReserveDuration = durationJSON(2 * time.Hour)
67			r.ReserveDeadline = timeJSON(t0.Add(2 * time.Hour))
68		}
69		if opts.mutate != nil {
70			opts.mutate(&r, &pol, &sess)
71		}
72	
73		// 结算已完成：预留余额为零，可用 = 初始 100 - 实际费用，策略已花费 = 实际费用。
74		b := backupV1{
75			Version:    backupVersion,
76			ExportedAt: timeJSON(t0.Add(-time.Minute)),
77			Accounts: []accountBackupV1{
78				{ID: "payer", Available: 100 - opts.actualFee, Reserved: 0, CreatedAt: timeJSON(t0.Add(-2 * time.Hour))},
79				{ID: "u1", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0.Add(-2 * time.Hour))},
80			},
81			Sessions: []sessionBackupV1{sess},
82			Policies: []policyBackupV1{pol},
83			Requests: []requestBackupV1{r},
84			// 既有账本：一条结算扣减记录；恢复后必须原样保留、不追加退款或超时记录。
85			Ledger: []ledgerEntryBackupV1{{
86				Kind: int(LedgerSettle), AccountID: "payer", RequestID: "late",
87				Amount: opts.actualFee, Reason: "settle actual fee", At: timeJSON(opts.settledAt),
88			}},
89		}
90		data, err := json.Marshal(&b)
91		if err != nil {
92			t.Fatal(err)
93		}
94		return data
95	}
