97	// assertSettleWindowRejected 恢复必须失败、包装 ErrBackupInvalid，错误信息点名
98	// 使用账户与请求编号并说明结算时刻不在有效预留期内，且不得返回部分钱包。
99	func assertSettleWindowRejected(t *testing.T, data []byte, at time.Time) string {
100		t.Helper()
101		w2, err := restoreAt(data, at)
102		if err == nil {
103			if w2 != nil {
104				t.Fatalf("invalid settled history restored a wallet: %+v", w2)
105			}
106			t.Fatal("invalid settled history restored without error")
107		}
108		if !errors.Is(err, ErrBackupInvalid) {
109			t.Fatalf("err = %v, want ErrBackupInvalid", err)
110		}
111		msg := err.Error()
112		if !strings.Contains(msg, `"u1"`) || !strings.Contains(msg, `"late"`) {
113			t.Fatalf("error %q must name usage account and request id", msg)
114		}
115		if !strings.Contains(msg, "reserve") {
116			t.Fatalf("error %q must explain the settlement is outside the reserve window", msg)
117		}
118		return msg
119	}
