121	// TestRestoreSettledWithinReserveWindowAccepted 验证合法结算时刻边界：恰在
122	// 预留完成时刻、截止前一纳秒都可接受；即使很久以后恢复（预留期早结束、申请
123	// 会话已到期/被吊销、策略已结束或被停用），已结算历史原样保留。
124	func TestRestoreSettledWithinReserveWindowAccepted(t *testing.T) {
125		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
126	
127		for _, approved := range []bool{false, true} {
128			pathName := map[bool]string{false: "direct", true: "approved"}[approved]
129			reservedAt := t0
130			deadline := t0.Add(2 * time.Hour)
131			if approved {
132				reservedAt = t0.Add(30 * time.Minute)
133				deadline = t0.Add(2*time.Hour + 30*time.Minute)
134			}
135	
136			t.Run(pathName+" settle exactly at reserved_at restores", func(t *testing.T) {
137				data := buildSettleWindowBackup(t, t0, settleWindowOpts{
138					approved: approved, actualFee: 20, settledAt: reservedAt,
139				})
140				if _, err := restoreAt(data, t0.Add(48*time.Hour)); err != nil {
141					t.Fatalf("settle exactly when reservation completes must be legal: %v", err)
142				}
143			})
144	
145			t.Run(pathName+" settle one nanosecond before deadline restores", func(t *testing.T) {
146				data := buildSettleWindowBackup(t, t0, settleWindowOpts{
147					approved: approved, actualFee: 20, settledAt: deadline.Add(-time.Nanosecond),
148				})
149				if _, err := restoreAt(data, t0.Add(48*time.Hour)); err != nil {
150					t.Fatalf("settle 1ns before deadline must be legal: %v", err)
151				}
152			})
153	
154			t.Run(pathName+" zero-fee settle within window restores", func(t *testing.T) {
155				data := buildSettleWindowBackup(t, t0, settleWindowOpts{
156					approved: approved, actualFee: 0, settledAt: deadline.Add(-time.Nanosecond),
157				})
158				w2, err := restoreAt(data, t0.Add(48*time.Hour))
159				if err != nil {
160					t.Fatalf("zero-fee in-window settle: %v", err)
161				}
162				r, _ := w2.Request("u1", "late")
163				if r.State != RequestSettled || r.ActualFee != 0 {
164					t.Fatalf("zero-fee settled request = %+v", r)
165				}
166				// 实际费用为零：预留已全额退回，策略已花费总额为零。
167				if bal, _ := w2.Balance("payer"); bal != (Balances{Available: 100, Reserved: 0}) {
168					t.Fatalf("balance = %+v, want full refund {100 0}", bal)
169				}
170				if pv, _ := w2.Policy("p"); pv.SpentTotal != 0 {
171					t.Fatalf("spent total = %d, want 0", pv.SpentTotal)
172				}
173			})
174		}
175	}
