177	// TestRestoreSettledHistoryPreservedLongAfterRestore 验证很久以后恢复时，期限内
178	// 已完成的结算仍保持已结算：实际费用、结算时间、余额、策略已花费总额与既有
179	// 账本原样保留，不追加退款或超时记录。
180	func TestRestoreSettledHistoryPreservedLongAfterRestore(t *testing.T) {
181		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
182		settledAt := t0.Add(90 * time.Minute) // 直接受理路径截止 t0+2h 之内
183		data := buildSettleWindowBackup(t, t0, settleWindowOpts{actualFee: 12, settledAt: settledAt})
184	
185		w2, err := restoreAt(data, t0.Add(30*24*time.Hour))
186		if err != nil {
187			t.Fatalf("legal settled history must restore long after deadline: %v", err)
