192		}
193		if r.ActualFee != 12 || !r.SettledAt.Equal(settledAt) {
194			t.Fatalf("settled history changed: fee %d at %v", r.ActualFee, r.SettledAt)
195		}
196		if !r.ReserveExpiredAt.IsZero() {
197			t.Fatalf("settled request must not gain a reserve-expired time: %v", r.ReserveExpiredAt)
198		}
199		// 初始 100：实际扣 12，退回差额 8。
200		if bal, _ := w2.Balance("payer"); bal != (Balances{Available: 88, Reserved: 0}) {
201			t.Fatalf("balance = %+v, want {88 0}", bal)
202		}
203		if pv, _ := w2.Policy("p"); pv.ReservedTotal != 0 || pv.SpentTotal != 12 {
204			t.Fatalf("policy totals = reserved %d spent %d, want 0/12", pv.ReservedTotal, pv.SpentTotal)
205		}
206		// 既有账本只有原结算记录，未因很久以后恢复而追加退款或超时记录。
207		led := w2.Ledger()
