213	// TestRestoreRejectsSettledAtOrAfterReserveDeadline 验证核心规则：启用预留
214	// 超时时，结算时刻等于或晚于预留截止时刻（含零实际费用）的已结算记录必须
215	// 拒绝；早于实际预留时刻也拒绝。直接受理与批准后预留两条路径一致。
216	func TestRestoreRejectsSettledAtOrAfterReserveDeadline(t *testing.T) {
217		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
218	
219		for _, approved := range []bool{false, true} {
220			pathName := map[bool]string{false: "direct", true: "approved"}[approved]
221			reservedAt := t0
222			deadline := t0.Add(2 * time.Hour)
223			if approved {
224				reservedAt = t0.Add(30 * time.Minute)
225				deadline = t0.Add(2*time.Hour + 30*time.Minute)
226			}
227	
228			cases := []struct {
229				name      string
230				actualFee int64
231				settledAt time.Time
232				reason    string
233			}{
234				{"settle exactly at deadline", 20, deadline, "reserve window"},
235				{"settle one nanosecond after deadline", 20, deadline.Add(time.Nanosecond), "reserve window"},
236				{"settle long after deadline", 20, deadline.Add(24 * time.Hour), "reserve window"},
237				{"zero-fee settle exactly at deadline", 0, deadline, "reserve window"},
238				{"zero-fee settle after deadline", 0, deadline.Add(time.Hour), "reserve window"},
239				{"settle before reserved_at", 20, reservedAt.Add(-time.Nanosecond), "before reserved_at"},
240			}
241			for _, tc := range cases {
242				t.Run(pathName+" "+tc.name, func(t *testing.T) {
243					data := buildSettleWindowBackup(t, t0, settleWindowOpts{
244						approved: approved, actualFee: tc.actualFee, settledAt: tc.settledAt,
245					})
246					// 即使恢复时刻远晚于截止、按超时规则本该全额退回，损坏的已结算
247					// 历史仍必须拒绝，不能当作有效扣费带回钱包。
248					msg := assertSettleWindowRejected(t, data, t0.Add(30*24*time.Hour))
249					if !strings.Contains(msg, tc.reason) {
250						t.Fatalf("error %q must explain %q", msg, tc.reason)
251					}
252				})
253			}
254		}
255	}
