257	// TestRestoreSettleWindowUsesApprovalReservedAt 验证审批路径的预留期自批准
258	// 成功、实际冻结费用的时刻起算，等待审批的时间不计入：晚于等待截止、但仍
259	// 早于“批准时刻+预留时长”的结算合法；用提交时间或审批等待期限替代预留期限
260	// 都会错误拒绝/接受。
261	func TestRestoreSettleWindowUsesApprovalReservedAt(t *testing.T) {
262		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
263		// 提交 t0、等待截止 t0+1h、t0+30m 批准预留、预留截止 t0+2h30m。
264	
265		// t0+2h：已过等待截止（t0+1h）、申请会话早已可过期，但仍在预留窗口
266		// [t0+30m, t0+2h30m) 内，必须接受——证明用的是实际预留时刻而非提交/等待期。
267		data := buildSettleWindowBackup(t, t0, settleWindowOpts{
268			approved: true, actualFee: 20, settledAt: t0.Add(2 * time.Hour),
269		})
270		if _, err := restoreAt(data, t0.Add(48*time.Hour)); err != nil {
271			t.Fatalf("settle after approval-wait deadline but within reserve window must be legal: %v", err)
272		}
273	
274		// 恰在预留截止 t0+2h30m：拒绝（对比若误用提交+2h=t0+2h 会被当成超时，
275		// 上一例已证明不会；本例锁定真正的截止时刻）。
276		data = buildSettleWindowBackup(t, t0, settleWindowOpts{
277			approved: true, actualFee: 20, settledAt: t0.Add(2*time.Hour + 30*time.Minute),
278		})
279		assertSettleWindowRejected(t, data, t0.Add(48*time.Hour))
280	}
281	
282	// TestRestoreSettleWindowSubSecondAndTimezoneInsensitive 验证时间比较依据保存
283	// 的完整时刻：纳秒精度保留，且不同时区表示的同一时刻判断一致。
284	func TestRestoreSettleWindowSubSecondAndTimezoneInsensitive(t *testing.T) {
285		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
286		deadline := t0.Add(2 * time.Hour)
287		loc := time.FixedZone("east", 5*60*60)
288	
289		// 截止前一纳秒，换成 +05:00 时区表示：仍是同一瞬间，必须接受。
290		before := deadline.Add(-time.Nanosecond).In(loc)
291		if before.Equal(deadline) {
292			t.Fatal("test setup: timezone conversion collapsed the instant")
293		}
294		data := buildSettleWindowBackup(t, t0, settleWindowOpts{actualFee: 20, settledAt: before})
295		if _, err := restoreAt(data, t0.Add(48*time.Hour)); err != nil {
296			t.Fatalf("same instant in a different timezone must restore: %v", err)
297		}
298	
299		// 截止时刻本身换时区表示：仍是同一瞬间，必须拒绝。
300		atDeadline := deadline.In(loc)
301		data = buildSettleWindowBackup(t, t0, settleWindowOpts{actualFee: 20, settledAt: atDeadline})
302		assertSettleWindowRejected(t, data, t0.Add(48*time.Hour))
303	}
304	
305	// TestRestoreSettledWithTimeoutDisabledHasNoSettleDeadline 验证关闭预留超时的
306	// 请求沿用原有结算规则：没有截止时刻，很久以后结算仍合法，不人为增加期限。
307	func TestRestoreSettledWithTimeoutDisabledHasNoSettleDeadline(t *testing.T) {
308		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
309		disable := func(_ *requestBackupV1, p *policyBackupV1, _ *sessionBackupV1) {
310			p.MaxReserveDuration = 0
311		}
312		// 结算时刻远在预留之后，且不携带任何截止时刻：照常恢复。
313		data := buildSettleWindowBackup(t, t0, settleWindowOpts{
314			actualFee: 20, settledAt: t0.Add(24 * time.Hour), mutate: disable,
315		})
316		// builder 默认写了 2h 的预留计时；关闭超时时必须清空，保持备份自洽。
317		var b backupV1
318		if err := json.Unmarshal(data, &b); err != nil {
319			t.Fatal(err)
320		}
321		b.Requests[0].ReserveDuration = durationJSON(0)
322		b.Requests[0].ReserveDeadline = timeJSON(time.Time{})
323		fixed, err := json.Marshal(&b)
324		if err != nil {
325			t.Fatal(err)
326		}
327		w2, err := restoreAt(fixed, t0.Add(30*24*time.Hour))
328		if err != nil {
329			t.Fatalf("settle with reserve timeout disabled must have no deadline: %v", err)
330		}
331		r, _ := w2.Request("u1", "late")
332		if r.State != RequestSettled || !r.ReserveDeadline.IsZero() {
333			t.Fatalf("timeout-disabled settled request = %+v", r)
334		}
335	}
336	
337	// TestRestoreSettledUnaffectedByLaterSessionPolicyLifecycle 验证只要结算在预留
338	// 有效期内合法完成，申请会话后来到期或被吊销、策略结束或被停用，都不应把已
339	// 合法完成的结算变成错误历史。
340	func TestRestoreSettledUnaffectedByLaterSessionPolicyLifecycle(t *testing.T) {
341		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
342		// 直接受理预留 [t0, t0+2h)；在 t0+1h 结算，此时会话、策略均已结束。
343		sessionExpired := func(_ *requestBackupV1, _ *policyBackupV1, s *sessionBackupV1) {
344			s.ExpiresAt = timeJSON(t0.Add(30 * time.Minute))
345		}
346		data := buildSettleWindowBackup(t, t0, settleWindowOpts{
347			actualFee: 20, settledAt: t0.Add(time.Hour), mutate: sessionExpired,
348		})
349		if _, err := restoreAt(data, t0.Add(48*time.Hour)); err != nil {
350			t.Fatalf("session expiring before a legal settle must not invalidate history: %v", err)
351		}
352	
353		sessionRevoked := func(_ *requestBackupV1, _ *policyBackupV1, s *sessionBackupV1) {
354			s.ExpiresAt = timeJSON(t0.Add(24 * time.Hour))
355			s.Revoked = true
356		}
357		data = buildSettleWindowBackup(t, t0, settleWindowOpts{
358			actualFee: 20, settledAt: t0.Add(time.Hour), mutate: sessionRevoked,
359		})
360		if _, err := restoreAt(data, t0.Add(48*time.Hour)); err != nil {
361			t.Fatalf("revoked application session must not invalidate a settled reservation: %v", err)
362		}
363	
364		// 策略在结算前已结束，但策略结束不缩短预留：截止 t0+2h 前的结算仍合法。
365		policyEnded := func(_ *requestBackupV1, p *policyBackupV1, _ *sessionBackupV1) {
366			p.EndsAt = timeJSON(t0.Add(30 * time.Minute))
367		}
368		data = buildSettleWindowBackup(t, t0, settleWindowOpts{
369			actualFee: 20, settledAt: t0.Add(time.Hour), mutate: policyEnded,
370		})
371		if _, err := restoreAt(data, t0.Add(48*time.Hour)); err != nil {
372			t.Fatalf("policy ending before deadline must not shorten the reserve window: %v", err)
373		}
374	
375		// 策略后来被停用：已合法完成的结算照常恢复。
376		policyDeactivated := func(_ *requestBackupV1, p *policyBackupV1, _ *sessionBackupV1) {
377			p.Deactivated = true
378			p.DeactivatedAt = timeJSON(t0.Add(90 * time.Minute))
379			p.DeactivatorAccountID = "payer"
380			p.DeactivateReason = "stopped"
381		}
382		data = buildSettleWindowBackup(t, t0, settleWindowOpts{
383			actualFee: 20, settledAt: t0.Add(time.Hour), mutate: policyDeactivated,
384		})
385		if _, err := restoreAt(data, t0.Add(48*time.Hour)); err != nil {
386			t.Fatalf("later policy deactivation must not invalidate a legal settle: %v", err)
387		}
388	}
389	
390	// TestRestoreRejectsBackupWhenAnySettledRequestOutOfWindow 验证同一备份中只要
391	// 有一笔已结算请求违反预留期限，整个恢复失败、不返回可用钱包，即使另一笔
392	// 已结算请求完全合法。
393	func TestRestoreRejectsBackupWhenAnySettledRequestOutOfWindow(t *testing.T) {
394		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
395		// 两笔零实际费用的已结算请求：late 恰在截止时刻（非法），ok 在窗口内。
396		data := buildSettleWindowBackup(t, t0, settleWindowOpts{
397			actualFee: 0, settledAt: t0.Add(2 * time.Hour), // late：恰在截止 t0+2h
398		})
399		var b backupV1
400		if err := json.Unmarshal(data, &b); err != nil {
401			t.Fatal(err)
402		}
403		b.Requests = append(b.Requests, requestBackupV1{
404			PolicyID: "p", RequestID: "ok", AccountID: "u1", PayerAccountID: "payer",
405			SessionID: "s1", Operation: "charge", Payee: "shop",
406			EstimatedFee: 20, ActualFee: 0, State: int(RequestSettled),
407			CreatedAt: timeJSON(t0), SettledAt: timeJSON(t0.Add(time.Hour)),
408			ReservedAt: timeJSON(t0), ReserveDuration: durationJSON(2 * time.Hour),
409			ReserveDeadline: timeJSON(t0.Add(2 * time.Hour)),
410		})
411		corrupt, err := json.Marshal(&b)
412		if err != nil {
413			t.Fatal(err)
414		}
415		assertSettleWindowRejected(t, corrupt, t0.Add(48*time.Hour))
416	}
417	
418	// TestRestoreLegalExportWithTimeoutSettleRoundTrips 端到端验证当前版本合法导出
419	// 文本继续兼容：在真实钱包中于预留窗口内结算，导出后于很久以后恢复，已结算
420	// 状态、金额与账本完整保留。
421	func TestRestoreLegalExportWithTimeoutSettleRoundTrips(t *testing.T) {
422		w, c := setupTimeout(t, time.Hour)
423		if _, err := w.Apply(timeoutApply()); err != nil { // r1 预留于 t0，截止 t0+1h
424			t.Fatal(err)
425		}
426		c.t = c.t.Add(30 * time.Minute)
427		if _, err := w.Settle("u1", "r1", 7); err != nil { // 窗口内结算
428			t.Fatal(err)
429		}
430		data, err := w.Export()
431		if err != nil {
432			t.Fatal(err)
433		}
434		w2, err := restoreAt(data, c.t.Add(30*24*time.Hour))
435		if err != nil {
436			t.Fatalf("legal in-window settled export must restore long after: %v", err)
437		}
438		r, _ := w2.Request("u1", "r1")
439		if r.State != RequestSettled || r.ActualFee != 7 {
440			t.Fatalf("restored settled request = %+v", r)
441		}
442		if l1, l2 := len(w.Ledger()), len(w2.Ledger()); l1 != l2 {
443			t.Fatalf("ledger entries added on restore: source %d restored %d", l1, l2)
444		}
445		if n := countKind(w2.Ledger(), LedgerReservationExpiration); n != 0 {
446			t.Fatalf("settled request gained timeout entries on restore: %d", n)
447		}
448		if bal, _ := w2.Balance("payer"); bal != (Balances{Available: 93, Reserved: 0}) {
449			t.Fatalf("balance = %+v, want {93 0}", bal)
450		}
451	}
452

