224			State:      int(RequestSettled),
225			CreatedAt:  timeJSON(t0.Add(-2 * time.Hour)),
226			ReservedAt: timeJSON(t0.Add(-2 * time.Hour)),
227			// 恰在预留完成时结算：无论是否启用预留超时都落在有效预留期起点，合法。
228			SettledAt: timeJSON(t0.Add(-2 * time.Hour)),
229		}
230		big := requestBackupV1{
231			PolicyID: "p-big", RequestID: "big", AccountID: "u2", PayerAccountID: "payer",
232			SessionID: "s2", Operation: "charge", Payee: "shop",
233			EstimatedFee:      bigFee,
234			State:             int(RequestReserved),
235			CreatedAt:         timeJSON(t0),
236			WaitDeadline:      timeJSON(t0.Add(time.Hour)),
237			ReservedAt:        timeJSON(t0),
238			ReserveDuration:   durationJSON(reserveDur),
239			ApproverAccountID: "payer",
240			DecidedAt:         timeJSON(t0),
241		}
242		if reserveDur > 0 {
243			big.ReserveDeadline = timeJSON(t0.Add(reserveDur))
244		}
245		small := requestBackupV1{
246			PolicyID: "p-big", RequestID: "small", AccountID: "u1", PayerAccountID: "payer",
247			SessionID: "s1", Operation: "charge", Payee: "shop",
248			EstimatedFee: smallFee,
249			State:        int(RequestPendingApproval),
250			CreatedAt:    timeJSON(t0),
251			WaitDeadline: timeJSON(t0.Add(time.Hour)),
252		}
253		// 已结算请求的预留时长快照必须与策略一致（备份自洽要求）。
254		settled.ReserveDuration = durationJSON(reserveDur)
255		if reserveDur > 0 {
256			settled.ReserveDeadline = timeJSON(t0.Add(-2 * time.Hour).Add(reserveDur))
257		}
258		b := backupV1{
259			Version:    backupVersion,
260			ExportedAt: timeJSON(t0),
261			Accounts: []accountBackupV1{
262				{ID: "payer", Available: 2, Reserved: bigFee, CreatedAt: timeJSON(t0)},
263				{ID: "u1", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0)},
264				{ID: "u2", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0)},
265			},
266			Sessions: []sessionBackupV1{
267				{ID: "s1", AccountID: "u1", DeviceID: "d1", ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0)},
268				{ID: "s2", AccountID: "u2", DeviceID: "d2", ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0)},
269				{ID: "sa", AccountID: "payer", DeviceID: "dev-approve", ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0)},
270			},
271			Policies: []policyBackupV1{{
272				ID: "p-big", PayerAccountID: "payer", AllowedAccountIDs: []string{"u1", "u2"},
273				Operation: "charge", Payee: "shop",
274				// 已结算请求提交于 t0-2h，时间窗起点须不晚于该时刻（提交时刻必须
275				// 落在策略时间窗内，备份自洽要求）。
276				StartsAt: timeJSON(t0.Add(-3 * time.Hour)), EndsAt: timeJSON(t0.Add(24 * time.Hour)),
277				MaxPerRequest:      math.MaxInt64,
278				MaxTotal:           math.MaxInt64,
279				ApprovalThreshold:  1,
280				ApprovalWait:       durationJSON(time.Hour),
281				MaxReserveDuration: durationJSON(reserveDur),
282				ReservedTotal:      bigFee,
283				SpentTotal:         spentActual,
284			}},
285			Requests: []requestBackupV1{settled, big, small},
286			Ledger:   []ledgerEntryBackupV1{},
287		}
288		data, err := json.Marshal(&b)
289		if err != nil {
290			t.Fatal(err)
291		}
292		return data
293	}
294	
295	// approveSmall 以出资账户会话 sa 批准 u1 的待审批请求 small。
296	func approveSmall(w *Wallet) (RequestView, error) {
297		return w.Approve("u1", "small", "sa", "dev-approve")
298	}
299	
300	// TestApproveSharedQuotaOverflowKeepsPending 验证待审批请求批准前重新执行
301	// 溢出安全的累计额度判断：其他请求已占用额度使本次批准越过 int64 上限时，
302	// 批准返回 ErrQuotaExceeded，请求继续待审批，提交时间、等待截止时间与决定
303	// 信息不变，不开始预留计时、不新增预留或批准记录；取消释放额度后期限内仍
304	// 可再次批准。
305	func TestApproveSharedQuotaOverflowKeepsPending(t *testing.T) {
306		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
307		data := buildApproveOverflowBackup(t, t0, 0)
308		w, err := restoreAt(data, t0)
309		if err != nil {
310			t.Fatalf("restore: %v", err)
311		}
312		before, err := w.Request("u1", "small")
313		if err != nil {
314			t.Fatal(err)
315		}
316		if before.State != RequestPendingApproval {
317			t.Fatalf("setup state = %v, want pending", before.State)
318		}
319		// 余额恰好够（2），但额度合计 MaxInt64-1 再加 2 越过 int64 上限。
320		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 2, Reserved: math.MaxInt64 - 2}) {
321			t.Fatalf("setup balance = %+v", bal)
322		}
323	
324		ledgerBefore := len(w.Ledger())
325		if _, err := approveSmall(w); !errors.Is(err, ErrQuotaExceeded) {
326			t.Fatalf("approve err = %v, want ErrQuotaExceeded", err)
327		}
328	
329		// 请求继续待审批，提交时间、等待截止时间与已有决定信息保持不变。
330		req, _ := w.Request("u1", "small")
331		if req.State != RequestPendingApproval {
332			t.Fatalf("state = %v, want still pending approval", req.State)
333		}
334		if !req.CreatedAt.Equal(before.CreatedAt) || !req.WaitDeadline.Equal(before.WaitDeadline) {
335			t.Fatalf("timing changed: created %v->%v deadline %v->%v",
336				before.CreatedAt, req.CreatedAt, before.WaitDeadline, req.WaitDeadline)
337		}
338		if !req.DecidedAt.Equal(time.Time{}) || req.ApproverAccountID != "" || req.RejectReason != "" {
339			t.Fatalf("decision fields changed on failed approve: %+v", req)
340		}
341		// 不开始预留计时。
342		if !req.ReservedAt.Equal(time.Time{}) || req.ReserveDuration != 0 || !req.ReserveDeadline.Equal(time.Time{}) {
343			t.Fatalf("reserve timing started on failed approve: %+v", req)
344		}
345		// 不新增预留或批准记录，余额与额度不变。
346		if got := len(w.Ledger()); got != ledgerBefore {
347			t.Fatalf("ledger grew by %d on failed approve", got-ledgerBefore)
348		}
349		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 2, Reserved: math.MaxInt64 - 2}) {
350			t.Fatalf("balance changed after failed approve: %+v", bal)
351		}
352		pv, _ := w.Policy("p-big")
353		if pv.ReservedTotal != math.MaxInt64-2 || pv.SpentTotal != 1 {
354			t.Fatalf("policy totals changed after failed approve: %+v", pv)
355		}
356	
357		// 期限内额度未释放时再次批准仍被拒绝。
358		if _, err := approveSmall(w); !errors.Is(err, ErrQuotaExceeded) {
359			t.Fatalf("second approve err = %v, want ErrQuotaExceeded", err)
360		}
361	
362		// 取消 u2 的大额预留，释放 MaxInt64-2 共享额度并全额退回余额。
363		if _, err := w.Cancel("u2", "big"); err != nil {
364			t.Fatal(err)
365		}
366		if bal, _ := w.Balance("payer"); bal != (Balances{Available: math.MaxInt64, Reserved: 0}) {
367			t.Fatalf("balance after cancel big = %+v", bal)
368		}
369		// 仍在等待期限内（时钟停在 t0，截止 t0+1h），释放后批准成功并预留 2。
370		req, err = approveSmall(w)
371		if err != nil {
372			t.Fatalf("approve after quota freed: %v", err)
373		}
374		if req.State != RequestReserved {
375			t.Fatalf("state = %v, want reserved", req.State)
376		}
377		if bal, _ := w.Balance("payer"); bal != (Balances{Available: math.MaxInt64 - 2, Reserved: 2}) {
378			t.Fatalf("balance after approve small = %+v", bal)
379		}
380		pv, _ = w.Policy("p-big")
381		if pv.ReservedTotal != 2 || pv.SpentTotal != 1 {
382			t.Fatalf("policy totals after approve small = %+v", pv)
383		}
384	}
385	
386	// TestApproveOverflowReleasedByReservationTimeout 验证批准前的额度检查会计入
387	// 按现有规则已经到期的预留释放：大额预留超时自动全额退回、释放额度后，期限
388	// 内的待审批请求可以成功批准；释放之前仍按超额度拒绝。
389	func TestApproveOverflowReleasedByReservationTimeout(t *testing.T) {
390		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
391		data := buildApproveOverflowBackup(t, t0, time.Minute)
392	
393		// 恢复于 t0：大额预留截止 t0+1m 尚未到期，批准 small 仍超额度。
394		w, err := restoreAt(data, t0)
395		if err != nil {
396			t.Fatalf("restore at t0: %v", err)
397		}
398		if _, err := approveSmall(w); !errors.Is(err, ErrQuotaExceeded) {
399			t.Fatalf("approve before timeout release err = %v, want ErrQuotaExceeded", err)
400		}
401		if r, _ := w.Request("u1", "small"); r.State != RequestPendingApproval {
402			t.Fatalf("small state = %v, want still pending", r.State)
403		}
404	
405		// 恢复于 t0+2m：大额预留已过截止时刻，恢复时自动全额退回并释放额度；
406		// small 的等待截止 t0+1h 尚未到，仍可批准。
407		w2, err := restoreAt(data, t0.Add(2*time.Minute))
408		if err != nil {
409			t.Fatalf("restore after deadline: %v", err)
410		}
411		if r, _ := w2.Request("u2", "big"); r.State != RequestReservationExpired {
412			t.Fatalf("big state = %v, want reservation expired", r.State)
413		}
414		if bal, _ := w2.Balance("payer"); bal != (Balances{Available: math.MaxInt64, Reserved: 0}) {
415			t.Fatalf("balance after timeout = %+v, want full refund", bal)
416		}
417		req, err := approveSmall(w2)
418		if err != nil {
419			t.Fatalf("approve after timeout release: %v", err)
420		}
421		if req.State != RequestReserved {
422			t.Fatalf("state = %v, want reserved", req.State)
423		}
424		if bal, _ := w2.Balance("payer"); bal != (Balances{Available: math.MaxInt64 - 2, Reserved: 2}) {
425			t.Fatalf("balance after approve small = %+v", bal)
426		}
427		pv, _ := w2.Policy("p-big")
428		if pv.ReservedTotal != 2 || pv.SpentTotal != 1 {
429			t.Fatalf("policy totals = %+v", pv)
430		}
431	}
432	
433	// TestApplyExactMaxInt64FillsQuota 验证单笔费用与上限均为 int64 最大值时
434	// 仍可正常受理（不缩小金额范围），占满后任何新费用都按超额度拒绝。
435	func TestApplyExactMaxInt64FillsQuota(t *testing.T) {
436		w, c := newTestWallet()
437		mustAccount(t, w, "payer", math.MaxInt64)
438		mustAccount(t, w, "u1", 0)
439		if _, err := w.CreateSession("s1", "u1", "d1", c.t.Add(time.Hour)); err != nil {
440			t.Fatal(err)
441		}
442		// 关闭审批：费用 MaxInt64 直接预留。
443		if err := w.SavePolicy(PolicySpec{
444			ID:                "p-direct",
445			PayerAccountID:    "payer",
446			AllowedAccountIDs: []string{"u1"},
447			Operation:         "charge",
448			Payee:             "shop",
449			StartsAt:          c.t.Add(-time.Hour),
450			EndsAt:            c.t.Add(24 * time.Hour),
451			MaxPerRequest:     math.MaxInt64,
452			MaxTotal:          math.MaxInt64,
453		}); err != nil {
454			t.Fatal(err)
455		}
456		in := RequestInput{
457			PolicyID: "p-direct", RequestID: "full", AccountID: "u1",
458			SessionID: "s1", DeviceID: "d1", Operation: "charge", Payee: "shop",
459			EstimatedFee: math.MaxInt64,
460		}
461		req, err := w.Apply(in)
462		if err != nil {
463			t.Fatalf("apply MaxInt64 fee: %v", err)
464		}
465		if req.State != RequestReserved {
466			t.Fatalf("state = %v, want reserved", req.State)
467		}
468		if bal, _ := w.Balance("payer"); bal != (Balances{Available: 0, Reserved: math.MaxInt64}) {
469			t.Fatalf("balance = %+v, want {0 MaxInt64}", bal)
470		}
471		// 额度已占满：再申请费用 1 必须超额度拒绝（used+1 越过 int64 上限；
472		// 余额虽同样不足，但额度判断在前，仍返回 ErrQuotaExceeded）。
473		in.RequestID = "one-more"
474		in.EstimatedFee = 1
475		if _, err := w.Apply(in); !errors.Is(err, ErrQuotaExceeded) {
476			t.Fatalf("apply after quota full err = %v, want ErrQuotaExceeded", err)
477		}
478	}
