1	package wallet
2	
3	import (
4		"encoding/json"
5		"errors"
6		"strings"
7		"testing"
8		"time"
9	)
10	
11	// buildApprovedTimingBackup 构造一笔“超门槛经批准后预留”的请求备份，所有
12	// 计时字段默认合法：提交于 t0、等待截止 t0+1h（策略窗口至 t0+24h、会话至
13	// t0+24h，均不抢先）、于 t0+30m 批准并预留、预留时长 2h。mutate 在余额
14	// 核对前调整请求/策略/会话的计时字段，以便构造各类不合法历史。
15	func buildApprovedTimingBackup(t *testing.T, t0 time.Time, state RequestState, mutate func(*requestBackupV1, *policyBackupV1, *sessionBackupV1)) []byte {
16		t.Helper()
17		const fee int64 = 20
18		r := requestBackupV1{
19			PolicyID: "p", RequestID: "big", AccountID: "u1", PayerAccountID: "payer",
20			SessionID: "s1", Operation: "charge", Payee: "shop",
21			EstimatedFee:      fee,
22			State:             int(state),
23			CreatedAt:         timeJSON(t0),
24			WaitDeadline:      timeJSON(t0.Add(time.Hour)),
25			ReservedAt:        timeJSON(t0.Add(30 * time.Minute)),
26			ReserveDuration:   durationJSON(2 * time.Hour),
27			ReserveDeadline:   timeJSON(t0.Add(2*time.Hour + 30*time.Minute)),
28			ApproverAccountID: "payer",
29			DecidedAt:         timeJSON(t0.Add(30 * time.Minute)),
30		}
31		pol := policyBackupV1{
32			ID: "p", PayerAccountID: "payer", AllowedAccountIDs: []string{"u1"},
33			Operation: "charge", Payee: "shop",
34			StartsAt:           timeJSON(t0.Add(-time.Hour)),
35			EndsAt:             timeJSON(t0.Add(24 * time.Hour)),
36			MaxPerRequest:      100,
37			MaxTotal:           1000,
38			ApprovalThreshold:  10,
39			ApprovalWait:       durationJSON(time.Hour),
40			MaxReserveDuration: durationJSON(2 * time.Hour),
41		}
42		sess := sessionBackupV1{
43			ID: "s1", AccountID: "u1", DeviceID: "d1",
44			ExpiresAt: timeJSON(t0.Add(24 * time.Hour)), CreatedAt: timeJSON(t0.Add(-2 * time.Hour)),
45		}
46		if mutate != nil {
47			mutate(&r, &pol, &sess)
48		}
49	
50		// 按终态补齐结算字段与自洽余额（校验在恢复时到期处理之前完成，故已预留
51		// 状态按备份记载的占用填写）。
52		var payerAvail, payerReserved, policyReserved, policySpent int64
53		switch state {
54		case RequestReserved:
55			payerAvail, payerReserved = 80, fee
56			policyReserved = fee
57		case RequestSettled:
58			r.ActualFee = fee
59			if time.Time(r.SettledAt).IsZero() {
60				r.SettledAt = r.ReservedAt
61			}
62			payerAvail = 80
63			policySpent = fee
64		case RequestCancelled:
65			// 已预留后取消：费用已全额退回。
66			payerAvail = 100
67		case RequestReservationExpired:
68			r.ReserveExpiredAt = r.ReserveDeadline
69			payerAvail = 100
70		default:
71			t.Fatalf("unsupported state %v", state)
72		}
73		pol.ReservedTotal, pol.SpentTotal = policyReserved, policySpent
74	
75		b := backupV1{
76			Version:    backupVersion,
77			ExportedAt: timeJSON(t0.Add(-time.Minute)),
78			Accounts: []accountBackupV1{
79				{ID: "payer", Available: payerAvail, Reserved: payerReserved, CreatedAt: timeJSON(t0.Add(-2 * time.Hour))},
80				{ID: "u1", Available: 0, Reserved: 0, CreatedAt: timeJSON(t0.Add(-2 * time.Hour))},
81			},
82			Sessions: []sessionBackupV1{sess},
83			Policies: []policyBackupV1{pol},
84			Requests: []requestBackupV1{r},
85			Ledger:   []ledgerEntryBackupV1{},
86		}
87		data, err := json.Marshal(&b)
88		if err != nil {
89			t.Fatal(err)
90		}
91		return data
92	}
93	
94	// assertApprovalTimingRejected 恢复必须失败、包装 ErrBackupInvalid，并在错误
95	// 信息中点名使用账户与请求编号；不得返回部分恢复的钱包。
96	func assertApprovalTimingRejected(t *testing.T, data []byte, at time.Time) string {
97		t.Helper()
98		w2, err := restoreAt(data, at)
99		if err == nil {
100			if w2 != nil {
101				t.Fatalf("invalid approval history restored a wallet: %+v", w2)
102			}
103			t.Fatal("invalid approval history restored without error")
104		}
105		if !errors.Is(err, ErrBackupInvalid) {
106			t.Fatalf("err = %v, want ErrBackupInvalid", err)
107		}
108		msg := err.Error()
109		if !strings.Contains(msg, `"u1"`) || !strings.Contains(msg, `"big"`) {
110			t.Fatalf("error %q must name usage account and request id", msg)
111		}
112		return msg
113	}
114	
115	// TestRestoreApprovedRequestTimingAccepted 验证期限内批准的请求（含恰在提交
116	// 时刻批准）合法；即使恢复时等待期限、申请会话与策略窗口均已结束，甚至该
117	// 笔预留在恢复时已超时将自动退回，也照常恢复且不重新计时。
118	func TestRestoreApprovedRequestTimingAccepted(t *testing.T) {
119		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
120	
121		t.Run("approved within window restores", func(t *testing.T) {
122			data := buildApprovedTimingBackup(t, t0, RequestReserved, nil)
123			w2, err := restoreAt(data, t0.Add(2*time.Minute))
124			if err != nil {
125				t.Fatalf("legal approved request: %v", err)
126			}
127			r, err := w2.Request("u1", "big")
128			if err != nil {
129				t.Fatal(err)
130			}
131			if r.State != RequestReserved {
132				t.Fatalf("state = %v, want reserved", r.State)
133			}
134		})
135	
136		t.Run("approved exactly at created_at restores", func(t *testing.T) {
137			data := buildApprovedTimingBackup(t, t0, RequestReserved, func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
138				r.ReservedAt = timeJSON(t0)
139				r.ReserveDeadline = timeJSON(t0.Add(2 * time.Hour))
140				r.DecidedAt = timeJSON(t0)
141			})
142			if _, err := restoreAt(data, t0.Add(time.Minute)); err != nil {
143				t.Fatalf("approval exactly at created_at must be legal: %v", err)
144			}
145		})
146	
147		t.Run("all windows ended at restore time still restores without retiming", func(t *testing.T) {
148			data := buildApprovedTimingBackup(t, t0, RequestReserved, func(r *requestBackupV1, p *policyBackupV1, _ *sessionBackupV1) {
149				// 关闭预留超时，使请求在很久以后仍处于已预留，专注核对审批计时。
150				p.MaxReserveDuration = 0
151				r.ReserveDuration = 0
152				r.ReserveDeadline = timeJSON(time.Time{})
153			})
154			w2, err := restoreAt(data, t0.Add(48*time.Hour))
155			if err != nil {
156				t.Fatalf("in-window approval must restore long after windows end: %v", err)
157			}
158			r, _ := w2.Request("u1", "big")
159			if !r.WaitDeadline.Equal(t0.Add(time.Hour)) || !r.ReservedAt.Equal(t0.Add(30*time.Minute)) {
160				t.Fatalf("timing rewritten: deadline %v reserved %v", r.WaitDeadline, r.ReservedAt)
161			}
162			if r.State != RequestReserved {
163				t.Fatalf("reserve with no timeout changed state = %v", r.State)
164			}
165		})
166	
167		t.Run("reservation due at restore time refunds but history still valid", func(t *testing.T) {
168			// 预留截止 t0+2h30：恢复时已超时，按原截止时刻全额退回；审批历史的
169			// 合法性只看备份记载的时间，不看恢复时刻。
170			data := buildApprovedTimingBackup(t, t0, RequestReserved, nil)
171			w2, err := restoreAt(data, t0.Add(24*time.Hour))
172			if err != nil {
173				t.Fatalf("valid history with due reservation: %v", err)
174			}
175			r, _ := w2.Request("u1", "big")
176			if r.State != RequestReservationExpired {
177				t.Fatalf("state = %v, want reservation expired", r.State)
178			}
179			if !r.ReserveExpiredAt.Equal(t0.Add(2*time.Hour + 30*time.Minute)) {
180				t.Fatalf("release time = %v, want original reserve deadline", r.ReserveExpiredAt)
181			}
182			if bal, _ := w2.Balance("payer"); bal != (Balances{Available: 100, Reserved: 0}) {
183				t.Fatalf("balance = %+v, want full refund", bal)
184			}
185		})
186	
187		t.Run("deadline bounded by policy end", func(t *testing.T) {
188			data := buildApprovedTimingBackup(t, t0, RequestReserved, func(r *requestBackupV1, p *policyBackupV1, _ *sessionBackupV1) {
189				p.EndsAt = timeJSON(t0.Add(30 * time.Minute))
190				// 策略结束最先发生；批准必须严格早于它。
191				r.WaitDeadline = timeJSON(t0.Add(30 * time.Minute))
192				r.ReservedAt = timeJSON(t0.Add(15 * time.Minute))
193				r.DecidedAt = timeJSON(t0.Add(15 * time.Minute))
194				r.ReserveDeadline = timeJSON(t0.Add(2*time.Hour + 15*time.Minute))
195			})
196			if _, err := restoreAt(data, t0.Add(time.Minute)); err != nil {
197				t.Fatalf("policy-end bounded deadline: %v", err)
198			}
199		})
200	
201		t.Run("deadline bounded by session expiry", func(t *testing.T) {
202			data := buildApprovedTimingBackup(t, t0, RequestReserved, func(r *requestBackupV1, _ *policyBackupV1, s *sessionBackupV1) {
203				s.ExpiresAt = timeJSON(t0.Add(20 * time.Minute))
204				r.WaitDeadline = timeJSON(t0.Add(20 * time.Minute))
205				r.ReservedAt = timeJSON(t0.Add(10 * time.Minute))
206				r.DecidedAt = timeJSON(t0.Add(10 * time.Minute))
207				r.ReserveDeadline = timeJSON(t0.Add(2*time.Hour + 10*time.Minute))
208			})
209			if _, err := restoreAt(data, t0.Add(time.Minute)); err != nil {
210				t.Fatalf("session-expiry bounded deadline: %v", err)
211			}
212		})
213	}
214	
215	// TestRestoreRejectsApprovedTimingOnReserved 验证已预留的批准路径请求：
216	// 等待截止缺失、被改长/改短，或批准发生在提交前、截止时刻或之后，都必须
217	// 让整个备份被拒绝——即使恢复时该预留已到期、原本将自动退回。
218	func TestRestoreRejectsApprovedTimingOnReserved(t *testing.T) {
219		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
220	
221		cases := []struct {
222			name      string
223			restoreAt time.Time
224			mutate    func(*requestBackupV1, *policyBackupV1, *sessionBackupV1)
225			reason    string
226		}{
227			{
228				name:      "missing wait deadline",
229				restoreAt: t0.Add(time.Minute),
230				mutate: func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
231					r.WaitDeadline = timeJSON(time.Time{})
232				},
233				reason: "missing wait deadline",
234			},
235			{
236				name:      "lengthened wait deadline",
237				restoreAt: t0.Add(time.Minute),
238				mutate: func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
239					r.WaitDeadline = timeJSON(t0.Add(2 * time.Hour))
240				},
241				reason: "does not match min",
242			},
243			{
244				name:      "shortened wait deadline",
245				restoreAt: t0.Add(time.Minute),
246				mutate: func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
247					r.WaitDeadline = timeJSON(t0.Add(15 * time.Minute))
248				},
249				reason: "wait deadline",
250			},
251			{
252				name:      "deadline claims policy end but stored later",
253				restoreAt: t0.Add(time.Minute),
254				mutate: func(r *requestBackupV1, p *policyBackupV1, _ *sessionBackupV1) {
255					p.EndsAt = timeJSON(t0.Add(30 * time.Minute))
256					// 正确截止应为 t0+30m，备份仍保存 t0+1h。
257				},
258				reason: "does not match min",
259			},
260			{
261				name:      "approval exactly at deadline",
262				restoreAt: t0.Add(time.Minute),
263				mutate: func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
264					r.ReservedAt = timeJSON(t0.Add(time.Hour))
265					r.DecidedAt = timeJSON(t0.Add(time.Hour))
266					r.ReserveDeadline = timeJSON(t0.Add(3 * time.Hour))
267				},
268				reason: "strictly before wait deadline",
269			},
270			{
271				name:      "approval after deadline",
272				restoreAt: t0.Add(time.Minute),
273				mutate: func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
274					r.ReservedAt = timeJSON(t0.Add(time.Hour + time.Nanosecond))
275					r.DecidedAt = timeJSON(t0.Add(time.Hour + time.Nanosecond))
276					r.ReserveDeadline = timeJSON(t0.Add(3*time.Hour + time.Nanosecond))
277				},
278				reason: "strictly before wait deadline",
279			},
280			{
281				name:      "approval before created_at",
282				restoreAt: t0.Add(time.Minute),
283				mutate: func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
284					r.ReservedAt = timeJSON(t0.Add(-time.Nanosecond))
285					r.DecidedAt = timeJSON(t0.Add(-time.Nanosecond))
286					r.ReserveDeadline = timeJSON(t0.Add(2*time.Hour - time.Nanosecond))
287				},
288				reason: "before created_at",
289			},
290			{
291				name:      "invalid history rejected even though reservation due for refund",
292				restoreAt: t0.Add(24 * time.Hour),
293				mutate: func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
294					// 批准恰在截止时刻；恢复时预留早就该自动退回，仍必须拒绝。
295					r.ReservedAt = timeJSON(t0.Add(time.Hour))
296					r.DecidedAt = timeJSON(t0.Add(time.Hour))
297					r.ReserveDeadline = timeJSON(t0.Add(3 * time.Hour))
298				},
299				reason: "strictly before wait deadline",
300			},
301		}
302		for _, tc := range cases {
303			t.Run(tc.name, func(t *testing.T) {
304				data := buildApprovedTimingBackup(t, t0, RequestReserved, tc.mutate)
305				msg := assertApprovalTimingRejected(t, data, tc.restoreAt)
306				if !strings.Contains(msg, tc.reason) {
307					t.Fatalf("error %q must explain %q", msg, tc.reason)
308				}
309			})
310		}
311	}
312	
313	// TestRestoreRejectsApprovedTimingAcrossTerminalStates 验证审批时限核对对所有
314	// “曾批准并实际预留”的状态统一适用：后来已结算、已预留后取消、预留超时的
315	// 请求也不能携带正常审批无法产生的时间。
316	func TestRestoreRejectsApprovedTimingAcrossTerminalStates(t *testing.T) {
317		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
318	
319		// approveAtDeadline 把批准（=预留）时刻挪到等待截止时刻——正常审批中该
320		// 时刻只能进入待审批过期终态，绝不可能预留成功。
321		approveAtDeadline := func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
322			r.ReservedAt = timeJSON(t0.Add(time.Hour))
323			r.DecidedAt = timeJSON(t0.Add(time.Hour))
324			r.ReserveDeadline = timeJSON(t0.Add(3 * time.Hour))
325		}
326		dropDeadline := func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
327			r.WaitDeadline = timeJSON(time.Time{})
328		}
329	
330		for _, tc := range []struct {
331			name   string
332			state  RequestState
333			mutate func(*requestBackupV1, *policyBackupV1, *sessionBackupV1)
334		}{
335			{"settled approval at deadline", RequestSettled, approveAtDeadline},
336			{"settled missing deadline", RequestSettled, dropDeadline},
337			{"reserved-cancelled approval at deadline", RequestCancelled, approveAtDeadline},
338			{"reserved-cancelled missing deadline", RequestCancelled, dropDeadline},
339			{"reservation-expired approval at deadline", RequestReservationExpired, approveAtDeadline},
340			{"reservation-expired missing deadline", RequestReservationExpired, dropDeadline},
341		} {
342			t.Run(tc.name, func(t *testing.T) {
343				data := buildApprovedTimingBackup(t, t0, tc.state, tc.mutate)
344				assertApprovalTimingRejected(t, data, t0.Add(time.Minute))
345			})
346		}
347	
348		// 对照：同样终态但批准时刻合法时应正常恢复。
349		for _, state := range []RequestState{RequestSettled, RequestCancelled, RequestReservationExpired} {
350			name := map[RequestState]string{
351				RequestSettled:            "settled",
352				RequestCancelled:          "reserved-cancelled",
353				RequestReservationExpired: "reservation-expired",
354			}[state]
355			t.Run(name+" legal approval restores", func(t *testing.T) {
356				data := buildApprovedTimingBackup(t, t0, state, nil)
357				if _, err := restoreAt(data, t0.Add(24*time.Hour)); err != nil {
358					t.Fatalf("legal %s request: %v", name, err)
359				}
360			})
361		}
362	}
363	
364	// TestRestoreDirectReserveNeedsNoApprovalInfo 验证未超门槛直接预留的请求不
365	// 被要求补上等待截止等审批信息（保持既有行为）。
366	func TestRestoreDirectReserveNeedsNoApprovalInfo(t *testing.T) {
367		t0 := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
368		data := buildApprovedTimingBackup(t, t0, RequestReserved, func(r *requestBackupV1, _ *policyBackupV1, _ *sessionBackupV1) {
369			// 费用 5 不超门槛 10：直接受理，不得携带批准/等待信息。
370			r.EstimatedFee = 5
371			r.ApproverAccountID = ""
372			r.DecidedAt = timeJSON(time.Time{})
373			r.WaitDeadline = timeJSON(time.Time{})
374			r.ReservedAt = timeJSON(t0)
375			r.ReserveDeadline = timeJSON(t0.Add(2 * time.Hour))
376		})
377		// 直接预留 5：调整账户预留余额与策略预留总额与之自洽。
378		var b backupV1
379		if err := json.Unmarshal(data, &b); err != nil {
380			t.Fatal(err)
381		}
382		for i := range b.Accounts {
383			if b.Accounts[i].ID == "payer" {
384				b.Accounts[i].Available = 95
385				b.Accounts[i].Reserved = 5
386			}
387		}
388		for i := range b.Policies {
389			if b.Policies[i].ID == "p" {
390				b.Policies[i].ReservedTotal = 5
391			}
392		}
393		fixed, err := json.Marshal(&b)
394		if err != nil {
395			t.Fatal(err)
396		}
397		w2, err := restoreAt(fixed, t0.Add(time.Minute))
398		if err != nil {
399			t.Fatalf("below-threshold direct reserve must not require approval info: %v", err)
400		}
401		r, _ := w2.Request("u1", "big")
402		if r.State != RequestReserved || !r.WaitDeadline.IsZero() || r.ApproverAccountID != "" {
403			t.Fatalf("direct reserve restored wrong: %+v", r)
404		}
405	}
