+func validateDirectReserveTiming(r *request) error {
+	if !r.reservedAt.Equal(r.createdAt) {
+		return fmt.Errorf("directly reserved request reserved_at %v must equal created_at %v", r.reservedAt, r.createdAt)
 	}
